$data = explode(' ', trim($input));
// First two are n and m
$n = (int)$data[0];
$m = (int)$data[1];
// Next m numbers
$a = array_slice($data, 2, $m);
$a = array_map('intval', $a);
sort($a);

if ($n > $m) {
    echo 0;
} elseif ($n == $m) {
    echo 1;
} else {
    // Compute frequencies
    $b = [];
    $c = 1;
    for ($i = 0; $i < $m - 1; $i++) {
        if ($a[$i] == $a[$i+1]) {
            $c++;
        } else {
            $b[] = $c;
            $c = 1;
        }
    }
    // Last group
