    sort($b);
    $r = count($b);
    $x = 0;
    for ($i = 1; $i <= 101; $i++) {
        $s = 0;
        for ($h = 0; $h < $r; $h++) {
            $s += (int)($b[$h] / $i);
        }
        if ($s >= $n) {
            $x = $i;
        }
    }
    echo $x;
}
?>

